import { z } from 'zod';
import { isoDate } from './setup';

export const attendanceStatuses = ['P', 'A', 'L', 'V'] as const;
export type AttendanceStatus = (typeof attendanceStatuses)[number];

export const attendanceDateSchema = isoDate;
export const attendanceMonthSchema = z
  .string()
  .regex(/^\d{4}-(0[1-9]|1[0-2])$/, 'Month must be YYYY-MM');

// `id` is generated by the client so a retried save is idempotent.
export const attendanceEntrySchema = z.object({
  id: z.uuid(),
  enrollmentId: z.uuid(),
  status: z.enum(attendanceStatuses),
});
export type AttendanceEntry = z.infer<typeof attendanceEntrySchema>;

export const attendanceSaveSchema = z
  .array(attendanceEntrySchema)
  .min(1)
  .max(300);

export interface AttendanceRow {
  enrollmentId: string;
  studentId: string;
  admissionNo: string;
  rollNo: number | null;
  nameEn: string;
  nameUr: string | null;
  status: AttendanceStatus;
  // false = nobody has saved this student for the day yet (status shows the default P)
  marked: boolean;
}

export interface AttendanceDay {
  sectionId: string;
  date: string;
  locked: boolean;
  lockDays: number;
  rows: AttendanceRow[];
}

export interface AttendanceSaveResult {
  inserted: number;
  unchanged: number;
  // Set when the date is past the lock window: nothing was saved, a request went to the principal.
  pendingApprovalId?: string;
}

export interface MonthRegisterRow {
  enrollmentId: string;
  admissionNo: string;
  rollNo: number | null;
  nameEn: string;
  nameUr: string | null;
  statuses: Record<string, AttendanceStatus>;
  totals: Record<AttendanceStatus, number>;
}

export interface MonthRegister {
  sectionId: string;
  month: string;
  days: string[];
  markedDays: string[];
  rows: MonthRegisterRow[];
}
